  };

  // Delete income stream
  const deleteIncomeStream = async id => {
    try {
      await axios.delete(`/income-streams/${id}`);
      dispatch({
        type: 'DELETE_INCOME_STREAM',
        payload: id,
      });
    } catch (err) {
      // Only log out if it's an auth error (401)
